import React, { useState, useRef } from 'react';

// Вспомогательная функция определения MIME-типа по расширению (для iOS)
const getFallbackMimeType = (fileName) => {
  const ext = fileName?.split('.').pop()?.toLowerCase();
  switch (ext) {
    case 'mov': return 'video/quicktime';
    case 'mp4': return 'video/mp4';
    case 'webm': return 'video/webm';
    case 'm4v': return 'video/x-m4v';
    default: return 'video/mp4'; // Безопасный дефолт
  }
};

const VideoUploader = ({
  onUploadSuccess,
  onError,
  hrefWebSite = '',
  currentUrl = '',
  maxSizeMb = 150,
  accept = 'video/mp4,video/quicktime,video/mov,video/webm',
  autoSaveToDb = false // Если true — сразу сохраняет URL в БД через /save-musician-video
}) => {
  const [progress, setProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadedUrl, setUploadedUrl] = useState(currentUrl);
  const [error, setError] = useState('');
  const [selectedFileName, setSelectedFileName] = useState('');
  const fileInputRef = useRef(null);

  const MAX_DURATION_SEC = 180; // 3 минуты

  // Основная функция загрузки
  const startUpload = async (fileToUpload) => {
    setIsUploading(true);
    setProgress(0);
    setError('');

    try {
      const telegramInitData = window.Telegram?.WebApp?.initData || '';
      const baseUrl = hrefWebSite ? hrefWebSite.replace(/\/+$/, '') : '';

      // ВАЖНО: Страховка от пустого file.type на iPhone
      const safeFileType = fileToUpload.type || getFallbackMimeType(fileToUpload.name);

      // 1. Получаем Presigned URL от нашего бэкенда
      const res = await fetch(`${baseUrl}/api-zvuk/upload/get-presigned-url`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${telegramInitData}`
        },
        body: JSON.stringify({
          fileName: fileToUpload.name,
          fileType: safeFileType
        })
      });

      if (!res.ok) throw new Error(`Ошибка сервера: ${res.status}`);

      const data = await res.json();
      if (!data.success) throw new Error(data.error || 'Ошибка получения ссылки');

      const { uploadUrl, publicUrl } = data;

      // 2. Отправляем бинарные данные напрямую в Cloudflare R2
      const xhr = new XMLHttpRequest();

      xhr.upload.onprogress = (event) => {
        if (event.lengthComputable) {
          const percent = Math.round((event.loaded / event.total) * 100);
          setProgress(percent);
        }
      };

      xhr.onload = async () => {
        if (xhr.status === 200 || xhr.status === 204) {
          
          // 3. Если включено autoSaveToDb — сразу сохраняем в Supabase
          if (autoSaveToDb) {
            try {
              const saveRes = await fetch(`${baseUrl}/api-zvuk/save-musician-video`, {
                method: 'POST',
                headers: {
                  'Content-Type': 'application/json',
                  'Authorization': `Bearer ${telegramInitData}`
                },
                body: JSON.stringify({ videoUrl: publicUrl })
              });
              const saveData = await saveRes.json();
              if (!saveData.success) throw new Error(saveData.error);
            } catch (dbErr) {
              console.error('Ошибка сохранения URL в БД:', dbErr);
            }
          }

          setUploadedUrl(publicUrl);
          setIsUploading(false);
          if (onUploadSuccess) onUploadSuccess(publicUrl);

        } else {
          setIsUploading(false);
          const errMsg = 'Хранилище R2 отклонило загрузку (ошибка авторизации/CORS)';
          setError(errMsg);
          if (onError) onError(errMsg);
        }
      };

      xhr.onerror = () => {
        setIsUploading(false);
        const errMsg = 'Сбой сети при прямой загрузке в R2';
        setError(errMsg);
        if (onError) onError(errMsg);
      };

      xhr.open('PUT', uploadUrl, true);
      // ВАЖНО: Заголовок должен СТРОГО совпадать с тем, что передали в get-presigned-url
      xhr.setRequestHeader('Content-Type', safeFileType);
      xhr.send(fileToUpload);

    } catch (err) {
      setIsUploading(false);
      const errMsg = err.message || 'Ошибка загрузки';
      setError(errMsg);
      if (onError) onError(errMsg);
    }
  };

  // Валидация файла и проверка длительности
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    setError('');

    if (!selectedFile) return;

    // 1. Проверка размера
    if (selectedFile.size > maxSizeMb * 1024 * 1024) {
      const msg = `Размер видео превышает ${maxSizeMb} МБ`;
      setError(msg);
      if (onError) onError(msg);
      return;
    }

    setSelectedFileName(selectedFile.name);

    // 2. Проверка длительности с обработкой ошибок кодеков
    const videoElement = document.createElement('video');
    videoElement.preload = 'metadata';
    const objectUrl = URL.createObjectURL(selectedFile);
    videoElement.src = objectUrl;

    videoElement.onloadedmetadata = () => {
      URL.revokeObjectURL(objectUrl);
      if (videoElement.duration > MAX_DURATION_SEC) {
        const msg = `Длительность видео больше 3 минут (${Math.round(videoElement.duration)} сек)`;
        setError(msg);
        if (onError) onError(msg);
      } else {
        startUpload(selectedFile);
      }
    };

    // Если браузер не смог прочитать метаданные (нестандартный кодек) — запускаем загрузку вопреки проверке
    videoElement.onerror = () => {
      URL.revokeObjectURL(objectUrl);
      console.warn('Не удалось прочитать метаданные видео, загружаем без предварительной проверки длительности');
      startUpload(selectedFile);
    };
  };

  return (
    <div className="p-4 border border-dashed border-slate-700 rounded-2xl text-center bg-slate-900/50">
      <input
        type="file"
        ref={fileInputRef}
        accept={accept}
        onChange={handleFileChange}
        style={{ display: 'none' }}
        disabled={isUploading}
      />

      {/* Кнопка выбора файла */}
      {!uploadedUrl && !isUploading && (
        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          className="w-full py-3 px-4 rounded-xl bg-pink-500 hover:bg-pink-600 text-white font-bold transition-all"
        >
          📁 Выбрать промо-видео с телефона
        </button>
      )}

      {/* Шкала прогресса */}
      {isUploading && (
        <div className="mt-2 text-left">
          <p className="text-xs text-slate-300 mb-2 truncate">⏳ Загружаем: {selectedFileName}</p>
          <div className="w-full bg-slate-800 h-2.5 rounded-full overflow-hidden">
            <div
              className="bg-pink-500 h-full rounded-full transition-all duration-200"
              style={{ width: `${progress}%` }}
            />
          </div>
          <span className="text-[11px] text-pink-400 mt-1 block text-right font-bold">{progress}%</span>
        </div>
      )}

      {/* Предпросмотр видео */}
      {uploadedUrl && !isUploading && (
        <div className="mt-2">
          <p className="text-xs text-emerald-400 font-bold mb-2">✅ Видео загружено!</p>
          <video
            src={uploadedUrl}
            controls
            playsInline
            className="w-full max-h-48 rounded-xl border border-slate-700 bg-black"
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="mt-3 text-xs text-slate-400 underline hover:text-white"
          >
            Заменить видео
          </button>
        </div>
      )}

      {error && <p className="text-xs text-red-400 mt-2 font-medium">⚠️ {error}</p>}
    </div>
  );
};

export default VideoUploader;