import React from 'react';

const GENRES = [
  'Рок', 'Поп', 'Джаз / Блюз', 'Реп / Хип-Хоп', 'Инди', 'Лаундж',
                'Электроника', 'Акустика', 'Фанк', 'Метал', 'Блюз', 'Каверы', 'Классика', 'Фолк'
];

export const GenreSelector = ({ selectedGenres = [], onChange }) => {
  const toggleGenre = (genre) => {
    window.Telegram?.WebApp?.HapticFeedback?.selectionChanged();
    
    if (selectedGenres.includes(genre)) {
      onChange(selectedGenres.filter((g) => g !== genre));
    } else {
      onChange([...selectedGenres, genre]);
    }
  };

  return (
    <div className="w-full space-y-3">
      <div className="flex justify-between items-center px-1">
        <label className="text-sm font-semibold text-gray-200">Выберите жанры</label>
      </div>

      <div className="flex flex-wrap gap-2.5">
        {GENRES.map((genre) => {
          const isSelected = selectedGenres.includes(genre);
          return (
            <button
              key={genre}
              type="button"
              onClick={() => toggleGenre(genre)}
              className={`px-4 py-2.5 rounded-xl text-sm font-medium transition-all duration-200 border active:scale-95 flex items-center gap-2 ${
                isSelected
                  ? 'bg-purple-600/20 text-purple-300 border-purple-500/60 shadow-lg shadow-purple-950/40 ring-1 ring-purple-500/30'
                  : 'bg-gray-900/60 text-gray-400 border-gray-800 hover:border-gray-700 hover:text-gray-200'
              }`}
            >
              <span>{genre}</span>
              {isSelected && (
                <span className="w-1.5 h-1.5 rounded-full bg-purple-400 animate-pulse" />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};